            // 1. 결제 처리
            Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
            order.assignPayment(payment);

            if (!payment.isSuccess()) {
                throw new RuntimeException("결제 실패: " + payment.getStatus());
            }

            log.info("결제 처리 완료: 주문ID={}, 결제ID={}", order.getId(), payment.getId());

            // 2. 배송 정보 생성
            OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
                    order,
                    requestDto.getReceiverName(),
                    requestDto.getReceiverPhone(),
                    requestDto.getPostalCode(),
                    requestDto.getAddress()
            );
            order.assignOrderShipment(shipment);
            log.info("배송 정보 생성 완료: 주문ID={}", order.getId());

            // 3. 상태 업데이트 (OrderStatus enum 사용)
            if (!order.getStatus().canTransitionTo(OrderStatus.PAYMENT_COMPLETED)) {
                throw new RuntimeException("결제 완료 상태로 전환할 수 없습니다. 현재 상태: " + order.getStatus());
            }
            order.updateStatus(OrderStatus.PAYMENT_COMPLETED);

            if (requestDto.isWarehouseStorage()) {
                // 창고 보관일 경우
                WarehouseStorage warehouseStorage = warehouseStorageCommandService.createOrderStorage(order, user);
                order.assignWarehouseStorage(warehouseStorage);
            User user = userQueryService.findByEmail(userEmail);
            Order order = orderRepository.findById(orderId)
                    .orElseThrow(() -> new OrderNotFoundException("해당 주문을 찾을 수 없습니다(ID: " + orderId + ")"));

            // 접근 권한 확인
            if (!order.getUser().getId().equals(user.getId())) {
                throw new OrderAccessDeniedException("해당 사용자는 이 주문을 처리할 권한이 없습니다.");
            }

            // 주문 정보 유효성 검사
            validatePaymentShipmentRequest(requestDto);

            try {
                // 2. 결제 처리
                Payment payment = paymentCommandService.processPayment(order, user, requestDto.getPaymentRequest());
                order.assignPayment(payment);
            } catch (Exception e) {
                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
                throw new OrderPaymentProcessingFailedException("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
            }

            try {
                // 3. 배송 정보 생성
                OrderShipment shipment = orderShipmentCommandService.createOrderShipment(
                        order,
                        requestDto.getReceiverName(),
                        requestDto.getReceiverPhone(),
                        requestDto.getPostalCode(),
                        requestDto.getAddress()
                );
                order.assignOrderShipment(shipment);
            } catch (Exception e) {
                log.error("배송 정보 처리 중 오류 발생: {}", e.getMessage(), e);
                throw new OrderShipmentProcessingFailedException("배송 정보 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
            }

                    order.getId(), requestDto.getBankName());

            // 은행 유효성 검증
            try {
                validateBank(requestDto.getBankName());
            } catch (Exception e) {
                throw new PaymentException(PaymentErrorCode.INVALID_BANK_INFO,
                        "유효하지 않은 은행 정보: " + requestDto.getBankName());
            }

            AccountPayment accountPayment = AccountPayment.builder()
                    .bankName(requestDto.getBankName())
                    .accountNumber(requestDto.getAccountNumber())
                    .accountHolder(requestDto.getAccountHolder())
                    .receiptRequested(requestDto.isReceiptRequested())
                    .paidAmount(requestDto.getPaidAmount())
                    .build();

            accountPayment.assignOrder(order);
            accountPayment.assignUser(user);
            accountPayment.updateStatus(PaymentStatus.PENDING);

            AccountPayment savedPayment = (AccountPayment) paymentRepository.save(accountPayment);
            log.info("계좌이체 결제 처리 완료: 주문ID={}, 결제ID={}, 상태={}",
                    order.getId(), savedPayment.getId(), savedPayment.getStatus());

